SET session_replication_role = 'replica';

-- ===== الفنيون =====
ON CONFLICT (name) DO NOTHING;

-- ===== العملاء (232 عميل) =====
-- نولّد الكود C-XXXX تلقائياً من الرقم التسلسلي


-- ✅ تم إدراج 231 عميل

-- ===== ربط الفنيين بالعملاء =====
UPDATE customers SET technician_id = (SELECT id FROM technicians WHERE name = 'حبيب' LIMIT 1) WHERE technician_id IS NULL AND secret_code IN (SELECT c.secret_code FROM customers c WHERE c.technician_id IS NULL);
UPDATE customers SET technician_id = (SELECT id FROM technicians WHERE name = 'رضوان' LIMIT 1) WHERE technician_id IS NULL AND secret_code IN (SELECT c.secret_code FROM customers c WHERE c.technician_id IS NULL);
UPDATE customers SET technician_id = (SELECT id FROM technicians WHERE name = 'ساجد' LIMIT 1) WHERE technician_id IS NULL AND secret_code IN (SELECT c.secret_code FROM customers c WHERE c.technician_id IS NULL);
UPDATE customers SET technician_id = (SELECT id FROM technicians WHERE name = 'عالم قير' LIMIT 1) WHERE technician_id IS NULL AND secret_code IN (SELECT c.secret_code FROM customers c WHERE c.technician_id IS NULL);

